script:
// Your CSS as text
var plan_fact_styles = `
    .tree .plan-fact-button {
        width: 24px; 
        height: 24px; 
        padding: 0; 
        border-radius: 50%;
    }
    .tree .plan-fact-button i {
        margin: 0;
    }
    .plan-fact-button.block, .block{
        color: #f44336;
    }
    .plan-fact-button.message, .message {
        color: #FF9800;
    }
    .plan-fact-button.warning, .warning {
        color: #FFEB3B;
    }
    .plan-fact-button.normal, .normal {
        color: #4CAF50;
    }
    .plan-fact-button.no-plan, .no-plan {
        color: #9E9E9E;
    }
    .modal-body div[data-fieldname="plan_fact_table"] .row-check.col {
        display: none;
    }
`
var pfStyleSheet = document.createElement("style");
pfStyleSheet.textContent = plan_fact_styles;
document.head.appendChild(pfStyleSheet);

function planFactButton( task ) {
    return  `<button class="btn btn-xs plan-fact-button" 
                data-docname="${task}"
                title="${__("Нет данных по трудозатратам")}">
                <i class="fa fa-info-circle"></i>
            </button>`;
}

async function refresh_tree_limits( project, nodes ) {
    let positions = nodes.map(function ( node ) {
            return {
                name: node.value,
                document_name: node.value,
                project: project
            };
        });

    frappe.call({
        method: (project_workload_assignment.pwrApi && project_workload_assignment.pwrApi.TIMESHEET_LIMITS) || 'project_workload_assignment.project_workload_api.calculate_timesheet_limits',
        args: {
            timesheet_name: "",
            positions: positions
        },
        callback: ({ message }) => {
            if ( message) {
                apply_tree_limit_styles(nodes, message);
            }
        }
    });
}

function apply_tree_limit_styles(nodes, results) {
    try {
        // Получаем данные через серверный метод
        nodes.forEach(node => {
            const button = $(`button.plan-fact-button[data-docname='${node.value }'`);
            let status = "no-data";

            let taskData = results.filter( (result) => 
                    result.position == node.value &&
                    ( result.planned_hours > 0 || result.total_hours > 0 )
                );

            if ( taskData && taskData.length > 0 ) {
                // Устанавливаем стиль кнопки на основе статуса
                status = get_max_status( taskData );

                // Формируем подсказку
                let tooltip = ( status != "no-data" && status != "no-plan" )
                    ? ( status == "normal"
                        ? __(`Трудозатраты в пределах планов/лимитов`)
                        : __(`Контроль трудозатрат по задаче`) )
                    : __("Не определены плановые трудозатраты");

                button.attr('title', tooltip);/**/
                button.off('click').on('click', { node: node, taskData: taskData }, show_plan_fact );
            } 

            button.addClass( status );
        });
    } catch (error) {
        console.error('Error updating button style:', error);
    }
}

function get_max_status( positions ) {
    let max_status = "no-data";

    for (const data of positions) {
        let status = data.status;

        if ( status == 'block' ) {
            return status;
        } else if ( status == 'message' ) {
            max_status = status;
        } else if ( status == 'warning' ) {
            if ( max_status != "message" ) {
                max_status = status;
            }
        } else if ( status == 'normal' ) {
            if ( max_status != "message" && max_status != "warning" ) {
                max_status = status;
            }
        } else {
            if ( max_status == "no-data" ) {
                max_status = status;
            }
        }
    };

    return max_status;
}

let shouldHighlightZeroPlans = false;

function show_plan_fact( e ) {
    e.preventDefault();
    e.stopPropagation();

    if (e.data.node && e.data.taskData ) {
        e.data.taskData.forEach(data => {
            data.users = frappe.utils.comma_and( data.hours_data.users );
        });

        let d = new frappe.ui.Dialog({
            title: __("План-факт трудозатрат"),
            fields: [
                {
                    label: __("Задача"),
                    fieldname: 'name',
                    fieldtype: "Data",
                    read_only: 1,
                    default: e.data.node.title
                },
                {
                    //label: __(""),
                    fieldname: 'plan_fact_table',
                    fieldtype: 'Table',
                    cannot_add_rows: 1,
                    cannot_delete_rows: 1,
                    in_place_edit: true,
                    on_setup: null,
                    fields: [
                        {
                            label: __('Роль'),
                            fieldname: 'role',
                            fieldtype: 'Data',
                            read_only: 1,
                            in_list_view: 1,
                            columns: 3
                        },
                        {
                            label: __("План"),
                            fieldname: 'planned_hours',
                            fieldtype: 'Float',
                            precision: 1,
                            read_only: 1,
                            in_list_view: 1,
                            columns: 1,
                            formatter: formatPlanField
                        },
                        {
                            label: __("Факт"),
                            fieldname: 'total_hours',
                            fieldtype: 'Float',
                            precision: 1,
                            read_only: 1,
                            in_list_view: 1,
                            columns: 1
                        },
                        {
                            label: __("%"),
                            fieldname: 'completion_percentage',
                            fieldtype: 'Percent',
                            precision: 1,
                            read_only: 1,
                            in_list_view: 1,
                            columns: 1,
                            formatter: formatField
                        },
                        {
                            label: __("Учтены трудозатраты от"),
                            fieldname: 'users',
                            fieldtype: 'Data',
                            read_only: 1,
                            in_list_view: 1,
                            columns: 4
                        }
                    ],
                    data: e.data.taskData
                }
            ],
            size: 'large',
            primary_action_label: __('Done'),
            primary_action(details) {
                d.hide();
                document.activeElement.blur();
            }
        });

        shouldHighlightZeroPlans = e.data.taskData.some(data => 
            data.plan_required && data.planned_hours <= 0
        );

        console.log('Should highlight zero plans:', shouldHighlightZeroPlans);

        // Проверяем, есть ли задачи с обязательным планом, но без плановых часов
        const tasksWithMissingPlan = e.data.taskData.filter(data => 
            data.plan_required && data.planned_hours <= 0
        );

        if (tasksWithMissingPlan.length > 0) {
            const warningDiv = $(`
                <div class="alert alert-danger" style="margin: 15px 0; display: flex; align-items: center; gap: 8px;">
                    <i class="fa fa-exclamation-triangle" style="font-size: 1.2em;"></i>
                    <div>
                        <strong>${__('Внимание!')}</strong> 
                        ${__('Для данной задачи обязательно указание плановых трудозатрат')}
                    </div>
                </div>
            `);
            d.$wrapper.find('.modal-body').prepend(warningDiv);
        }

        d.show();
    } else {
        frappe.msgprint(__('Нет данных для отображения.'));
    }
}

const formatPlanField = (val, field, options, doc) => {
    return doc.planned_hours ? val : "<span class='" + doc.status + "'>" + val + "</span>" ;
}

const formatField = (val, field, options, doc) => {
    return doc.planned_hours ? "<span class='" + doc.status + "'>" + val + "</span>" : val;
}

