        if (tasksWithMissingPlan.length > 0) {
            const warningDiv = $(`
                <div class="alert alert-danger" style="margin: 15px 0; display: flex; align-items: center; gap: 8px;">
                    <i class="fa fa-exclamation-triangle" style="font-size: 1.2em;"></i>
