                        ${__('Для данной задачи обязательно указание плановых трудозатрат')}
                    </div>
                </div>
            `);
            d.$wrapper.find('.modal-body').prepend(warningDiv);
        }

        d.show();
    } else {
        frappe.msgprint(__('Нет данных для отображения.'));
    }
}

