function setup_task_tree_layout() {
    var dragging = false;
    var leftColumn = $('.left-column');
    var rightColumn = $('.right-column');
    var border = $('.draggable-border');

    border.mousedown(function(e) {
        e.preventDefault();
        dragging = true;
    });

    $(document).mouseup(function() {
        dragging = false;
    });

    $(document).mousemove(function(e) {
        if (dragging) {
            var offset = e.pageX - leftColumn.offset().left;
            var newLeftWidth = offset / leftColumn.parent().width() * 100;
            var newRightWidth = 100 - newLeftWidth;

            if (newLeftWidth < 30) {
            } else if (newRightWidth < 2) {
            } else {
                leftColumn.css('width', newLeftWidth + '%');
                rightColumn.css('width', newRightWidth + '%');
                localStorage.setItem(`layout_widths_${cur_tree.view_name}_${cur_tree.args.doctype}`, newLeftWidth );
            }
        }
    });
};

function _set_initial_layout_width( layout_block ) {
    let leftWidth = localStorage.getItem(`layout_widths_${cur_tree.view_name}_${cur_tree.args.doctype}`);

    if ( leftWidth ) {
        var rightWidth = 100 - leftWidth;
        $('.left-column').css('width', leftWidth + '%');;
        $('.right-column').css('width', rightWidth + '%');
    }
    let is_xl = $(document).width() > 1400; 
    let is_fw = $(document.body).hasClass( "full-width" );
    if ( (is_xl && !is_fw) || (!is_xl && is_fw) ) {
        frappe.ui.toolbar.toggle_full_width();
    }
}

