let resizeLoaded = false;
//Изменяемая ширина колонок
function makeResizable() {
    // Изменение ширины столбцов в List View - тикет ISS-2023-00116
    const resultContainer = document.querySelector('#page-Tree\\/Task .layout-main-section');
    //const resultContainer = document.querySelector('.page-content');
    if (!resultContainer) return;

    const header = resultContainer.querySelector('.tree-header');
    const listHeaderSubject = header.querySelector('.tree-row');
    let listRowContainers = resultContainer.querySelectorAll('.tree-node');
    //listHeaderSubject.classList.add("ellipsis");
    
    // Получаем сохраненные ширины столбцов
    const storedWidths = JSON.parse(localStorage.getItem(`column_widths_${cur_tree.view_name}_${cur_tree.args.doctype}`) || '{}');

    // Все заголовки столбцов
    const headers = listHeaderSubject.querySelectorAll('.details-cell, .main-col');
    headers.forEach((headerDiv, index) => {
        const fieldnameSpan = headerDiv.querySelector('span');
        const fieldname = fieldnameSpan 
            ? fieldnameSpan.textContent.trim() 
            : headerDiv.textContent.trim();

        // Если это последний столбец (например, assign_to), не меняем ширину
        //if (fieldname === 'Assign To' || !fieldname) return;

        // Устанавливаем сохраненную ширину, если она есть
        if (storedWidths[fieldname]) {
            const newWidth = getWidth( storedWidths[fieldname] );
            resize( headerDiv, newWidth, index );
        }

        if ( !resizeLoaded ) {
            // Создаем элемент для изменения ширины
            const resizer = document.createElement('div');
            resizer.classList.add('column-resizer');
            resizer.setAttribute("data-index", index)
            resizer.addEventListener('mousedown', initResize);
    
            headerDiv.style.position = 'relative';
            headerDiv.appendChild(resizer);
        }
    });
    
    resizeLoaded = true;

    function initResize(e) {
        const headerDiv = e.target.parentElement;
        const startX = e.clientX;
        const startWidth = headerDiv.offsetWidth;
        const index = e.target.getAttribute("data-index");
        listRowContainers = resultContainer.querySelectorAll('.tree-node');
        
        function doResize(event) {
            const newWidth = getWidth( startWidth + (event.clientX - startX) );
            resize( headerDiv, newWidth, index );
        }

        function stopResize() {
            document.removeEventListener('mousemove', doResize);
            document.removeEventListener('mouseup', stopResize);

            const fieldnameSpan = headerDiv.querySelector('span');
            const fieldname = fieldnameSpan ? fieldnameSpan.textContent.trim() : null;

            if (fieldname) {
                storedWidths[fieldname] = headerDiv.offsetWidth;
                localStorage.setItem(`column_widths_${cur_tree.view_name}_${cur_tree.args.doctype}`, JSON.stringify(storedWidths));
            }
        }

        document.addEventListener('mousemove', doResize);
        document.addEventListener('mouseup', stopResize);
    }
    
    // Обновляем ширину в строках данных
    function resize(headerDiv, newWidth, index) {
        if ( index == 0 ) {
            headerDiv.parentElement.style.minWidth = "fit-content";
            headerDiv.parentElement.style.maxWidth = "fit-content";
        }
        
        headerDiv.style.minWidth = newWidth;
        headerDiv.style.maxWidth = newWidth;
                    
        listRowContainers.forEach(container => {
            const row = container.querySelector('.tree-row');
            if (row) {
                const cells = row.querySelectorAll('.details-cell, .tree-link');
                if (cells[index]) {
                    cells[index].style.minWidth = newWidth;
                    cells[index].style.maxWidth = newWidth;
                }
            }
        });
    }
    
    function getWidth( width ) {
        return "max( 2vw, " + width + "px)";
    }
}

