function validate_relation(frm , row, cdt, cdn, field="predecessor") {
    // call server validate
    frappe.call({
        method: "validate_relation",
        args: {
            parent_successor: frm.doc.name,
            predecessor: row.predecessor,
            rel_type: row.type,
            buffer_days: row.buffer_days || 0
        },
        callback: function(r) {
            if (!r || !r.message) return;
            let res = r.message;
            if (res.ok) {
                // ok — keep row
                frappe.show_alert({message: __('Relation validated'), indicator: 'green'});
            } else {
                frappe.model.set_value(cdt, cdn, field, "");  
                frappe.throw( res.error + (res.path ? ('<br>Path: ' + res.path.join(' -> ')) : '') );
            }
        }
    });
}

// Helper: quick check of direct relations and highlight fields
function _tds_quick_check(frm) {
    // call get_relations_for_task and mark warnings
    if (frm.is_new()) return;
    frappe.call({
        method: "get_relations_for_task",
        args: {task: frm.doc.name},
        callback: function(r) {
            //TODO Переделать на даты по календарю!
            if (!r || !r.message) return;
            let data = r.message;
            let has_conflict = false;
            // check predecessors
            (data.predecessors || []).forEach(function(pr) {
                // simple check: if FS and predecessor.exp_end + buffer > current start -> conflict
                if (!pr.exp_end_date) return;
                if (!frm.doc.exp_start_date) return;
                // convert strings to Date for simple compare (ignoring business days here)
                let pred_end = new Date(pr.exp_end_date);
                let cur_start = new Date(frm.doc.exp_start_date);
                // we only do a naive check client-side, server preview is authoritative
                if (pr.type === __("FS (Finish → Start)")) {
                    let buf = parseInt(pr.buffer_days || 0);
                    pred_end.setDate(pred_end.getDate() + buf);
                    if (pred_end > cur_start) {
                        has_conflict = true;
                    }
                }
            });
            // set indicator
            if (has_conflict) {
                frm.set_df_property('exp_start_date', 'read_only', false);
                // add message
                frm.dashboard.add_comment(__('Warning: some dependencies may be violated'), 'orange');
            }
        }
    });
}

