let _save_data = {};
let _timerId = {};

async function _on_date_change(task, start, end) {
    console.log( task + ": " + start + "-" + end );
    _save_data[ task.id ] = {
        task: task,
        start: start,
        end: end,
    };
    
    if ( _timerId[ task.id ] ) {
        clearTimeout( _timerId[ task.id ] );
    }
    
    _timerId[ task.id ] = setTimeout(async () => {
        await _save_node( task.id );
        _save_data[ task.id ] = {};
    }, 1000);
}

async function _save_node( task_id ) {
    let task = _save_data[ task_id ].task;
    let start = _save_data[ task_id ].start;
    let end = _save_data[ task_id ].end;
    
    let has_changes= false;
    let save_fields = [];
    let save_values = [];
    let old_values = [];

    if ( frappe.datetime.get_day_diff( task.start, start ) ) {
        old_values.push( task.node.exp_start_date );
        task.start = frappe.datetime.obj_to_str( start );
        setNodeValue( task.id, "exp_start_date", task.start );
        save_fields.push( "exp_start_date" );
        save_values.push( task.start );
        has_changes = true;
    }
    if ( frappe.datetime.get_day_diff( task.end, end ) ) {
        old_values.push( task.node.exp_end_date );
        task.end = frappe.datetime.obj_to_str( end );
        setNodeValue( task.id, "exp_end_date", task.end );
        save_fields.push( "exp_end_date" );
        save_values.push( task.end );
        has_changes = true;
    }
    if ( has_changes ) {
        await saveNodeData( task_id, save_fields, save_values, old_values );
    }
}

