    let bar = tree.gantt.get_bar( node.value );
    let task = tree.gantt.get_task( node.value );
    bar.group.classList.remove( task.custom_class );  
    tree.gantt.update_task( node.value, _get_task( node ) );
    tree.gantt.hide_popup();
    bar.update_arrow_position();
    
    if ( !ignpre_dependents ) {
        let dependents = tree.gantt.get_all_dependent_tasks( node.value );
        dependents.forEach( dependent => {
            let dependent_task = tree.gantt.get_task( dependent );
            update_node_gantt( tree, dependent_task.node, true );
        });
    }/**/
}


function click_node_gantt( tree, node, hide ) {
    console.log("***** Gantt: click_node_gantt ****** " );
    if ( tree.gantt ) {
        node._expanded = !hide;
        _toggle_children( tree.gantt.nodes, node.value, hide );
        tree.gantt.refresh( get_tasks( tree.gantt.nodes ) );
        tree.gantt.set_scroll_position( node.exp_start_date );
        _bind_holiday_labels();
    }
}

function _bind_holiday_labels( ) {
    $(".holiday-highlight").each(function(index, e) {
        const i = $(".label_" + e.classList[1]);
        if (!i)
            return;
        let s;
        this.onmouseenter = r => {
            s = setTimeout( () => {
                i.addClass("show"),
                i.css( "left", ( r.clientX  ) + "px"),
                i.css( "top", (r.clientY ) + "px")
            }
            , 300)
        }
        ,
        this.onmouseleave = r => {
            clearTimeout(s),
            i.removeClass("show")
        }
    } );
}

function _toggle_children( nodes, parent, hide ) {
    for ( node of nodes ) {
        if ( node.parent_task == parent ) {
            node._hide = hide;
            
            if ( node._expanded ) {
                _toggle_children( nodes, node.value, hide );
            }
        }
    }
}

async function add_nodes_to_gantt( tree, new_nodes ) {
    console.log("***** Gantt: add_nodes_to_gantt ****** " );
    let nodes = add_child_nodes( tree.gantt?.nodes, new_nodes );
    
    if ( !tree.gantt ) {
        let holidays = await _get_holidays( tree.root_value );
        tree.gantt = _build_gantt( nodes, holidays );
        _bind_holiday_labels();
        _sync_scroll();
    } else {
        //tree.gantt.refresh( get_tasks( nodes ) );
    }
    
    tree.gantt.nodes = nodes;
    return tree.gantt;
}

async function _get_holidays( project ) {
    let holidays_data = [];
    let r = await frappe.db.get_value('Project', project, ['holiday_list', 'company']);
    
    if ( r && r.message ) {
        let values = r.message;
        let holidays = values.holiday_list;
        
        if ( !holidays && values.company ) {
            let c_r = await frappe.db.get_value('Company', values.company, ['default_holiday_list']);
            holidays = c_r?.message?.default_holiday_list;
        }
        
        if ( holidays ) {
            let hd_r = await frappe.db.get_doc('Holiday List', holidays );
            holidays_data = hd_r?.holidays?.map( (d) => ( { 
                name: __(frappe.utils.html2text( d.description )), 
                date: d.holiday_date, 
                weekly_off: d.weekly_off } ) );
        }
    }
    return holidays_data;
}

function add_child_nodes( current, nodes ) {
    let tree_nodes = [];
    let skip_childs = [];
    let has_root = nodes.some( (node) => ( node.parent_task == null ) )
    
    if ( !current || has_root ) {
        tree_nodes = nodes;
    } else {
        for ( cur_node of current ) {
            if ( skip_childs.includes( cur_node.parent_task ) ) {
                skip_childs.push( cur_node.value );
            } else {
                tree_nodes.push( cur_node );
            
                if ( nodes.some( (node) => ( node.parent_task == cur_node.value ) ) ) {
                    tree_nodes = tree_nodes.concat( nodes );
                    skip_childs.push( cur_node.value );
                }
            }
        }
    } 
    
    return tree_nodes;
}

function get_tasks( nodes ) {
    let tasks = [];
    
    if ( nodes) {
        tasks = nodes.filter( (node) => !node._hide )
            .map((node) => ( _get_task( node ) ));
    }
    
    return tasks;
}

function _get_task( node ) {
    return {
                id: node.value,  
                name: node.subject,  
                start: node.exp_start_date ? ( node.exp_start_date + " 00:00:00" ) : node.creation,
                end: node.exp_end_date ? node.exp_end_date  + ( node.is_milestone ? " 00:00:00" : " 23:59:59" ) : ( node.exp_start_date ? ( node.exp_start_date + " 00:00:00" ) : node.creation ),
                progress: node.progress,                                            // Progress percentage (0-100)
                dependencies: node.relations.map(r=>r.predecessor),//.join(","),       // Comma-separated task IDs that this task depends on (e.g., '1,2,3')
                //duration: '4d',
                thumbnail: ( node.is_milestone ) ? "/assets/dinext_projects/images/rhombus.png" : null,
                custom_class: node.priority || "",
                node: node,
                color: _get_task_color( node ),
                color_progress: 'var(--bg-green)',
            };
}

function _get_task_color( node ) {
    switch( node.status ) {
        case 'Open': 
            return null;
        case 'Working': 
            return null;//"var(--bg-blue)";
        case 'Pending Review': 
            return "var(--bg-dark-blue)";
        case 'Overdue': 
            return "var(--alert-bg-danger)";
        case 'Template': 
            return null;
        case 'Completed': 
            return "var(--bg-green)";
        case 'Cancelled': 
            return "var(--bg-light-gray)";               
        default:
            return null;
    }
}

