async function refresh_task_dependencies( project, node ) {
    refresh_tasks_dependencies( project, [node] )
}

async function refresh_tasks_dependencies( project, nodes ) {
    nodes.forEach(node => {
        const $task = $(`.tree-link[data-label='${node.value}']`);
        $task.removeClass( "conflict" );
        
        const $field = $task.parent().find(".details-cell.conflict");
        $field.removeClass( "conflict" );
        $field.attr('title', ""); 
    });
    
    refresh_tree_dependencies( project, nodes );
}

async function refresh_tree_dependencies( project, nodes ) {
    let positions = nodes.map(function ( node ) {
        return {
            name: node.value,
            project: project,
            subject: node.subject,
            exp_start_date: node.exp_start_date,
            exp_end_date: node.exp_end_date

        };
    });
    
    frappe.call({
        method: 'check_dependencies_for_tasks',
        args: {
            project: project,
            tasks: positions,
        },
        callback: ({ message }) => {
            if ( message) {
                apply_task_tree_relations_styles( message );
            }
        }
    });
}

function apply_task_tree_relations_styles(results) {
    try {
        // Получаем данные через серверный метод
        results.forEach(taskData => {
            if ( taskData.checked_task && taskData.violations.length > 0 ) {
                const $task = $(`.tree-link[data-label='${taskData.checked_task}']`);
                $task.addClass( "conflict" );
                
                taskData.violations.forEach(violation => {
                    let $field = $task.parent().find(".details-cell.exp_" + violation.violated_field + "_date");
                    $field.addClass( "conflict" );
                    $field.attr('title', violation.message); 
                });
            } 
        });
    } catch (error) {
        console.error('Error updating relations style:', error);
    }
}

const LARGE_AMOUNT_THRESHOLD = 200;

// Main preview function 
function _tds_preview_tree(task, direction, cbfunc) {
    frappe.call({
        method: "preview_propagation",
        args: {
            changed_task: task,
            direction: direction
        },
        callback: function(r) {
            if (!r || !r.message) return;
            let msg = r.message;
            _tds_show_preview_dialog_tree(msg.preview, cbfunc);
        }
    });
}

function _tds_show_preview_dialog_tree(preview_list, cbfunc) {
    if (!preview_list || preview_list.length === 0) {
        frappe.show_alert(__('Не выявлено нарушений зависимостей вниз по дереву задач'));
        return;
    }
    // Create dialog 
    let d = new frappe.ui.Dialog({
        title: __('Необходимые изменения для устранения нарушений зависимостей задач'),
        size: 'extra-large',
        fields: [{
            fieldname: 'dependencies_rows',
            fieldtype: 'Table',
            cannot_add_rows: 1,
            cannot_delete_rows: 1,
            in_place_edit: true,
            fields: [
                { label: __('Задача'), fieldname: 'subject', fieldtype: 'Data', read_only: 1, in_list_view: 1, columns: 2 }, 
                { label: __("Текущ. начало"), fieldname: 'current_start', fieldtype: 'Date', read_only: 1, in_list_view: 1, columns: 1 }, 
                { label: __("Текущ. окончание"), fieldname: 'current_end', fieldtype: 'Date', read_only: 1, in_list_view: 1, columns: 1 }, 
                { label: __("Предл. начало"), fieldname: 'proposed_start', fieldtype: 'Date', read_only: 1, in_list_view: 1, columns: 1 }, 
                { label: __("Предл. окончание"), fieldname: 'proposed_end', fieldtype: 'Date', read_only: 1, in_list_view: 1, columns: 1 }, 
                { label: __("Причины"), fieldname: 'reasons', fieldtype: 'Data', read_only: 1, in_list_view: 1, columns: 4 }
            ],
            data: preview_list
        }],
        primary_action_label: __('Выполнить выбранные'),
        primary_action: function() {
            const seleted = this.fields_dict.dependencies_rows.grid.get_selected_children();
            if (!seleted.length) {
                frappe.msgprint(__('Необходимо выбрать изменения'));
                return;
            }
            // Prepare changes payload 
            let changes = seleted.map(function(p) {
                return {
                    task: p.task,
                    proposed_start: p.proposed_start,
                    proposed_end: p.proposed_end
                };
            });
            // If large, run async 
            if (changes.length > LARGE_AMOUNT_THRESHOLD) {
                frappe.confirm(__('This operation affects {0} tasks and may take a long time. Run in background?', [changes.length]), function() {
                    frappe.call({
                        method: "apply_propagation",
                        args: {
                            changes: JSON.stringify(changes),
                            mode: "async"
                        },
                        callback: function(r) {
                            if (r && r.message && r.message.job_id) {
                                frappe.show_alert(__('Propagation started in background (job {0})', [r.message.job_id]));
                            } else {
                                frappe.show_alert(__('Propagation enqueued'));
                            }
                            d.hide();
                            cbfunc("async", changes);
                            setTimeout(function() {
                                refresh_tasks_dependencies( 
                                    cur_tree?.root_value, 
                                    changes.map( c=> cur_tree?.nodes[ c.task ].data )
                                    );
                                }, 5000);
                        }
                    });
                }, function() {
                    // cancel 
                });
            } else {
                // sync apply 
                frappe.call({
                    method: "apply_propagation",
                    args: {
                        changes: JSON.stringify(changes),
                        mode: "sync"
                    },
                    callback: function(r) {
                        if (r && r.message && r.message.success) {
                            frappe.show_alert(__('Выполнены изменения: {0}', [r.message.changed]));
                        } else {
                            frappe.msgprint(__('Error applying changes'));
                        }
                        d.hide();
                        cbfunc("sync", changes);
                        refresh_tasks_dependencies( 
                            cur_tree?.root_value, 
                            changes.map( c=> cur_tree?.nodes[ c.task ].data )
                            );
                    }
                });
            }
        },
        secondary_action_label: __('Закрыть'),
        secondary_action: function() {
            d.hide();
        }
    });
    d.show();
}

